#!/usr/bin/env python3
"""Apply Fable's Batch 2 de-cloning cure by consolidation and differentiated editorial copy."""
from __future__ import annotations

import hashlib, json, re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'data'
def load(p): return json.loads(p.read_text())
def dump(p,v): p.write_text(json.dumps(v,indent=2,sort_keys=True)+'\n')
def words(sections): return len(re.findall(r"\b[\w'-]+\b",' '.join(x for s in sections for x in s['paragraphs'])))

money_path=DATA/'money-page-specs.json'; money=load(money_path)
expanded=next(x for x in money['pages'] if x['page_id']=='expanded-curated-glp1-programs-2026')
shipping=next(x for x in money['pages'] if x['page_id']=='glp1-shipping-review-times-2026')
expanded.update({
 'title':'Seven additional online GLP-1 programs: an evidence-transparency comparison',
 'h1':'Seven additional online GLP-1 programs, compared by what they actually disclose',
 'description':'A source-bound comparison of seven additional programs across price, oversight, coverage language, fulfillment, and unresolved evidence gaps.',
 'intro':[
  "This page exists because a long affiliate roster is not the same thing as a useful shortlist. We started with the remaining GLP-1 relationships from the Phase 0 registry, then removed rows that crossed a hard boundary: an exact FDA warning-letter match, no positive commercial terms, a source page too thin to support a fair profile, or wording that blurred compounded semaglutide with a branded FDA-approved product. Seven programs survived that screen for held editorial comparison: HealthRX, AgelessRx, Wellorithm, Enhance.MD, Synergy RX, BreezeMeds, and Serena Health. Surviving the screen does not authorize promotion. It means only that a first-party page supplied enough dated material to compare disclosure quality without inventing a medical outcome, a clinician credential, a service area, or a hidden fee. The score rewards what can be checked: published price structure, a described review workflow, self-pay or HSA/FSA language, review evidence, and fulfillment detail. A low score may describe missing public information rather than poor care; a high score is not a clinical recommendation.",
  "The seven rows tell different stories. HealthRX and AgelessRx publish recognizable starting figures and multiple logistics details. Wellorithm distinguishes an introductory month from later recurring pricing, which matters when a shopper models more than the first invoice. Enhance.MD publishes separate figures for compounded semaglutide and tirzepatide and describes prescription approval as a condition of service. BreezeMeds combines a one-month format with a stated delivery window and no-insurance language. Serena Health pairs four-, eight-, and twelve-week formats with self-pay and HSA/FSA statements. Synergy RX confirms a GLP-1 pathway and physician-led review but leaves GLP-specific price and several operating terms unstated on the captured page; those cells stay unknown rather than borrowing prices from unrelated products. Across every row, compounded products are labeled as compounded, not FDA-approved. Official provider pages are cited for commercial facts, while FDA pages control the product-status warning. This is a research inventory for comparison, not a diagnosis, prescription, or assurance that any program will accept a particular person."
 ],
 'verdict':{'label':'Best disclosure depth in this seven-program expansion','provider':'HealthRX','program_id':'healthrx','one_line':'HealthRX supplied the broadest combined evidence for published starting prices, review timing, HSA/FSA use, financing, shipping, and a no-long-term-commitment statement; product eligibility and final cost still require provider confirmation.'},
 'section_winners':[
  {'criterion':'Recurring-price clarity','provider':'Wellorithm','reason':'Its captured page separates month-one figures from later monthly figures for both compounded semaglutide and compounded tirzepatide, reducing introductory-price ambiguity.'},
  {'criterion':'Commitment-format disclosure','provider':'Serena Health','reason':'Its first-party page names four-, eight-, and twelve-week program formats and says there are no hidden fees; cancellation details still need confirmation.'},
  {'criterion':'Unknowns handled honestly','provider':'Synergy RX','reason':'The comparison leaves GLP-specific price, insurance, and delivery timing unknown because the captured GLP page did not state them; unrelated product prices were not substituted.'}
 ],
 'cons':[
  'None of these seven rows has promotion authorization or a live affiliate route; the page cannot be used as a checkout directory.',
  'First-party pages can change, and several omit cancellation, service-area, insurance, pharmacy, or final recurring-cost details that a shopper should confirm directly.',
  'The comparison evaluates evidence transparency, not medical appropriateness, treatment quality, weight-loss results, or whether a prescription will be issued.'
 ],
 'faq':[
  {'q':'Why are these seven called additional curated programs?','a':'They are the remaining programs that passed a narrow content-evidence screen after the six already covered in Batch 1. Curation here means enough first-party material for a held comparison. It does not mean endorsement, safety certification, promotion approval, or evidence that the program fits a specific person.'},
  {'q':'Why were MadeMed and Telos RX not added?','a':'Their captured first-party landing pages were too sparse to support a balanced commercial profile. The fail-closed rule is to leave them outside the curated comparison until stronger price, workflow, product-status, and fulfillment evidence is archived.'},
  {'q':'Why is Synergy RX included when its GLP price is unknown?','a':'Its page supplied a recognizable GLP pathway and physician-led review language, so it can be compared on those disclosed dimensions. The table deliberately preserves unknown price and operating fields rather than importing numbers from non-GLP products or making an inference.'},
  {'q':'Does a published starting price equal the amount I would pay?','a':'No. Starting figures can depend on product, route, introductory period, eligibility, dose, consultation, laboratory work, supplies, shipping, or later-month pricing. Use the row as a question generator and request a written all-in quote before payment.'},
  {'q':'Are compounded semaglutide or tirzepatide FDA-approved?','a':'No. FDA states that compounded drugs are not FDA-approved and are not reviewed before marketing for safety, effectiveness, or quality. A provider may describe a program that uses a compounded product, but that does not convert the product into an FDA-approved drug.'},
  {'q':'Why does public-review transparency affect the score?','a':'The rubric reserves fifteen percent for independently inspectable review evidence. In this expansion the archived provider pages did not supply a consistent, source-cleared review dataset, so the score does not manufacture one. That lowers totals while keeping the comparison reproducible.'},
  {'q':'What should I verify after narrowing the list?','a':'Ask for the exact prescribed product and formulation, clinician-review sequence, licensed pharmacy identity, total recurring charge, included consultations and supplies, delivery method, refill timing, cancellation deadline, refund terms, state availability, and the process for urgent questions or adverse events.'},
  {'q':'Why are all action buttons held?','a':'Affiliate destinations remain link-dark because redirector terms have not been verified and the operator has not authorized promotion or go-live. The displayed routes are inert descriptors used for QA, not active outbound links.'}
 ]
})
shipping.update({
 'title':'Online GLP-1 review and shipping timelines: six disclosure patterns compared',
 'h1':'Review time is not delivery time: compare six online GLP-1 timelines',
 'description':'A logistics-first audit separating clinician review, pharmacy processing, carrier delivery, refill timing, and missing service-area evidence.',
 'intro':[
  "Online weight-management pages often compress several clocks into one promise. A clinical questionnaire can be reviewed quickly while pharmacy processing, prescription routing, cold-chain preparation, carrier pickup, weather, address validation, and state-law checks happen later. This logistics audit refuses to merge those stages. HealthRX says approval can occur within two days and separately describes seven-to-ten-day shipping. AgelessRx cites four-to-six business days after processing. Wellorithm presents a twenty-four-to-forty-eight-hour consultation and a later five-to-seven-business-day shipment. Enhance.MD describes approval within twenty-four hours and delivery in roughly five-to-seven business days. BreezeMeds places review in a two-to-four-day window and delivery in a five-to-seven-business-day window. Serena Health describes review within twenty-four to forty-eight hours and delivery in five-to-seven business days. These are provider statements captured on one date, not guaranteed arrival dates, and they do not prove that every medication, destination, or refill follows the same route.",
  "A useful fulfillment comparison asks what happens between approval and the doorstep. The page should say whether shipping is included, which pharmacy dispenses the prescription, whether the package requires temperature controls, how tracking is issued, what happens after a missed delivery, and whether a refill request must be reviewed again. Most captured pages answer only part of that chain. HealthRX names licensed U.S. compounding pharmacies and shipping terms. AgelessRx references accredited compounding pharmacies and included shipping. Wellorithm says the medication is compounded and refrigerated but leaves some pharmacy-identification details unresolved. Enhance.MD says FDA-registered pharmacies and nationwide availability, while the captured evidence does not turn that language into product approval. BreezeMeds and Serena Health describe included or free shipping but still leave questions about carrier exceptions and replacement policy. The practical result is a timeline worksheet, not a race: confirm each milestone in writing before relying on a date for travel, a refill, or continuity of care."
 ],
 'verdict':{'label':'Most segmented timeline disclosure','provider':'HealthRX','program_id':'healthrx','one_line':'HealthRX separates review timing from a seven-to-ten-day shipping statement and identifies licensed U.S. compounding pharmacies; actual fulfillment remains prescription- and destination-dependent.'},
 'section_winners':[
  {'criterion':'Fastest stated review window','provider':'Enhance.MD','reason':'The captured page says prescription approval is typically within twenty-four hours, while also making approval contingent on clinical review.'},
  {'criterion':'Shortest stated post-processing delivery band','provider':'AgelessRx','reason':'Its captured page says delivery is typically four to six business days after processing, a narrower logistics claim than the other compared pages.'},
  {'criterion':'Best separation of two clocks','provider':'BreezeMeds','reason':'The source describes a two-to-four-day review period and a separate five-to-seven-business-day delivery period, which avoids treating review as doorstep arrival.'}
 ],
 'cons':[
  'Provider timeline language is a snapshot, not a service-level agreement; weekends, pharmacy queues, prescription changes, weather, and destination rules can alter fulfillment.',
  'Several pages do not identify every dispensing pharmacy, replacement process, carrier exception, temperature excursion policy, or refill-review requirement.',
  'A faster advertised review or shipment does not establish better care, medical eligibility, medication availability, or a safer product.'
 ],
 'faq':[
  {'q':'What is the difference between review time and shipping time?','a':'Review time covers the provider decision process after intake. Shipping time generally begins only after approval, prescription routing, and pharmacy processing. A page that states one clock but not the other leaves the total elapsed time unknown.'},
  {'q':'Should I add the two published windows together?','a':'Only as a rough planning range, not a promise. The windows may use different starting events, exclude weekends, depend on processing completion, or change by medication and destination. Ask the provider to define the start and end event for each clock.'},
  {'q':'What does free or included shipping leave unanswered?','a':'It may not explain carrier, speed, signature requirements, insulated packaging, tracking, replacement after loss, temperature-excursion handling, or surcharges for certain destinations. Included price and documented fulfillment quality are separate questions.'},
  {'q':'Does an FDA-registered pharmacy mean the compounded drug is FDA-approved?','a':'No. Facility registration or other pharmacy language does not establish that a compounded drug has FDA approval. FDA says compounded drugs are not FDA-approved and are not reviewed before marketing for safety, effectiveness, or quality.'},
  {'q':'Why is state availability relevant to a timeline?','a':'A provider and dispensing pharmacy must be able to serve the destination under applicable licensing and prescribing rules. If state coverage is unstated or eligibility changes, the order may pause before fulfillment begins.'},
  {'q':'What should I ask before traveling?','a':'Confirm whether a refill review is due, the earliest pharmacy processing date, estimated carrier handoff, tracking method, package-storage instructions, destination eligibility, and the process if delivery is delayed. Do not change treatment timing based on this comparison.'},
  {'q':'Why is Synergy RX absent from this logistics table?','a':'Its captured GLP page did not provide enough source-clear timing detail for this specific comparison. It remains in the broader evidence-transparency page with unknown logistics rather than receiving an inferred delivery estimate.'},
  {'q':'Can Clinic Scout guarantee these windows?','a':'No. Clinic Scout archives and compares provider statements. It does not dispense medication, control review queues, operate a pharmacy, transport packages, or guarantee that a stated range applies to a particular order.'}
 ]
})
money['pages']=money['pages'][:3]+[expanded,shipping]
money['schema']='glp-clinic-scout-phase2-batch2-money-pages-v3-decloned'
dump(money_path,money)

blog_path=DATA/'blog/content-batch.json'; blog=load(blog_path); old=blog['articles']
A=old[6]; B=old[7]; M=old[10]
A.update({'title':'HealthRX vs AgelessRx: price architecture, commitments, and fulfillment evidence','h1':'HealthRX vs AgelessRx: compare the bill, cadence, and evidence gaps','description':'A source-bound comparison of how HealthRX and AgelessRx describe price, plan duration, review, pharmacy language, and delivery.','primary_keyword':'HealthRX vs AgelessRx cost and terms'})
A['sections']=[
 {'h2':'The useful question is not “which starts lower?”','paragraphs':["AgelessRx advertises compounded semaglutide from $150 per month and compounded tirzepatide from $250 per month on the captured plan page. HealthRX advertises compounded semaglutide from $169 per month and compounded tirzepatide from $279 per month. Those figures create an apparent $19 or $29 gap, but a starting-price subtraction is not a total-cost comparison. The pages differ in plan cadence, included support, processing language, and what remains unstated. A defensible comparison therefore keeps the figures beside their qualifiers instead of declaring a universal bargain.","Both rows are held editorial candidates, not active recommendations. Neither provider has a live affiliate route here. Prescription issuance depends on provider review, final cost may vary, and the comparison does not establish that either service is medically appropriate. Compounded semaglutide and tirzepatide are not FDA-approved; the provider sources describe the commercial programs, while FDA controls that product-status statement."]},
 {'h2':'Two billing shapes, not one interchangeable monthly price','paragraphs':["AgelessRx presents monthly starting figures and says there is no membership fee, no contract, and no obligation. Its page also presents three- and six-month options with savings. HealthRX describes a no-long-term-commitment model and publishes starting figures by product. These phrases answer different questions. “No membership fee” addresses a separate platform charge; “no contract” addresses duration; “starting at” addresses only the visible entry point. None by itself proves the final recurring invoice.","Before payment, request a written breakdown that names medication, formulation, plan length, first charge, later charge, consultation, supplies, shipping, laboratory work if any, refill-review cost, cancellation deadline, and refund rule. A quote that does not distinguish an introductory amount from a recurring amount is not complete enough for budgeting."]},
 {'h2':'HealthRX makes more of the administrative path visible','paragraphs':["The HealthRX capture says provider approval can occur within two days, refers to ongoing clinical guidance and check-ins, accepts HSA/FSA funds, offers financing, and says insurance generally does not cover compounded medications. It also names licensed U.S. compounding pharmacies and a seven-to-ten-day shipping period. Together those statements describe more of the path from intake to payment to fulfillment, which is why HealthRX scores higher on disclosure depth.","Disclosure depth is not clinical quality. The page does not let Clinic Scout verify a particular clinician, prescription, pharmacy shipment, state eligibility, or patient outcome. It simply reduces the number of commercial blanks a shopper must fill. A high transparency score should be read as “more of the operating model was visible in the archived source,” not “better treatment.”"]},
 {'h2':'AgelessRx is clearer about optional plan length','paragraphs':["AgelessRx distinguishes monthly access from three- and six-month formats and says longer plans can reduce cost. That is useful for a shopper comparing commitment length. The same page states that HSA/FSA funds are accepted and describes delivery in four to six business days after processing. Its pharmacy language references accredited compounding pharmacies. Those details create a compact self-pay proposition with a relatively explicit cadence.","The tradeoff is that the captured evidence leaves some fields less developed than HealthRX, including certain insurance, cancellation, and service-area particulars. “No contract” should not be treated as a complete cancellation policy. Ask when a renewal locks, whether a processed prescription can be refunded, how an unused multi-month balance is handled, and whether pricing changes if the prescribed product or plan changes."]},
 {'h2':'Review speed and doorstep speed are separate','paragraphs':["HealthRX’s two-day approval statement and seven-to-ten-day shipping statement describe different clocks. AgelessRx’s four-to-six-business-day delivery statement begins after processing. Neither should be converted into a guaranteed order-to-door promise. Pharmacy routing, clinician questions, prescription changes, weekends, carrier events, and destination rules can extend the elapsed time.","For continuity planning, ask both providers to define intake completion, clinician decision, pharmacy acceptance, carrier handoff, and estimated arrival. Request the tracking and replacement process as well. This comparison does not provide dosing or refill-timing advice; it shows which logistical questions the first-party pages answer and which remain open."]},
 {'h2':'Product labels deserve exact language','paragraphs':["Both captured offers concern compounded products. FDA states that compounded drugs are not FDA-approved and are not reviewed before marketing for safety, effectiveness, or quality. Provider references to licensed or accredited pharmacies do not change that product status. Likewise, a familiar ingredient name does not justify substituting a branded trademark for the compounded formulation.","A pre-purchase record should name the prescribed ingredient, dosage form, whether it is compounded or an FDA-approved branded drug, the dispensing pharmacy, and the reason the prescriber selected it. Clinic Scout does not verify or recommend that selection. The editorial safeguard is narrower: do not blur categories, do not imply approval, and do not copy a provider claim beyond what the archived source supports."]},
 {'h2':'A practical side-by-side worksheet','paragraphs':["HealthRX currently leads this pair on combined operational disclosure: payment options, review timing, support, pharmacy language, and a separate shipping period. AgelessRx currently leads on the visibility of optional three- and six-month plan formats and a lower advertised starting figure in the capture. Either advantage can disappear if the final written quote adds a different recurring amount, product, or condition.","Use a seven-line worksheet: product status; first invoice; recurring invoice; plan duration; included clinical contacts; pharmacy and delivery milestones; cancellation and refund terms. Fill only documented answers. If one provider cannot answer a line, mark it unknown. That discipline is more useful than selecting by the lowest number in a headline."]}
]
B.update({'title':'Wellorithm vs Enhance.MD: introductory pricing versus a flat monthly offer','h1':'Wellorithm vs Enhance.MD: decode month one, later months, and fulfillment','description':'A focused comparison of introductory versus recurring pricing, administration routes, approval language, payment tools, and unresolved terms.','primary_keyword':'Wellorithm vs Enhance MD recurring price'})
B['sections']=[
 {'h2':'One comparison, two very different price stories','paragraphs':["Wellorithm’s captured page is built around a transition: compounded semaglutide is shown at $149 for month one and $229 monthly afterward, while compounded tirzepatide is shown at $249 for month one and $429 monthly afterward. Enhance.MD presents $99 per month for compounded semaglutide and $249 per month for compounded tirzepatide. The numbers cannot be compared responsibly without preserving the time period attached to each one.","An introductory figure answers “what may the first invoice look like?” A recurring figure answers “what may later invoices look like?” A flat advertised monthly figure still needs confirmation of medication, formulation, included services, shipping, and whether the amount changes after clinical review. The table keeps those categories separate and does not calculate a treatment budget for an individual."]},
 {'h2':'Wellorithm reveals the promotional step-up','paragraphs':["Wellorithm deserves credit for putting later-month figures next to the introductory month. That disclosure makes the promotional jump visible before checkout. Its capture also mentions oral and injectable forms, HSA/FSA payment, financing, refrigerated shipping, a twenty-four-to-forty-eight-hour consultation, and five-to-seven-business-day delivery language. These details make a multi-stage offer easier to audit.","The same breadth creates more questions. A shopper should identify which form the displayed figure covers, when the recurring amount begins, whether the charge changes with the prescribed course, what refrigeration statement applies to the exact shipment, and which pharmacy will dispense it. A broad menu is not evidence that every option is available or appropriate."]},
 {'h2':'Enhance.MD leads with a compact monthly proposition','paragraphs':["Enhance.MD’s capture presents simple monthly figures, says prescription approval is typically within twenty-four hours, describes access to licensed providers and nutrition support, accepts HSA/FSA funds, and says insurance is not accepted. It also presents nationwide availability and five-to-seven-business-day delivery language. For someone building a self-pay checklist, the page surfaces several decision inputs without the introductory-versus-recurring arithmetic found at Wellorithm.","The simplicity should still be tested with a written quote. Confirm whether the advertised amount includes medication, consultation, supplies, shipping, support, and every recurring platform charge. Confirm state availability rather than treating “nationwide” as proof for a particular destination. And keep product status exact: the captured programs concern compounded medication; compounded drugs are not FDA-approved."]},
 {'h2':'Route-of-administration language changes the evidence burden','paragraphs':["Wellorithm mentions both oral and injectable options. That distinction matters commercially because a headline price may attach to one route, one formula, or one introductory configuration. Enhance.MD’s captured offer is presented around compounded semaglutide and tirzepatide monthly pricing. Neither page allows a publisher to assume interchangeability among routes, formulations, or branded drugs.","Ask the provider to put the route and formulation next to the price in writing. If the response uses a brand trademark, ask whether the actual product is the FDA-approved branded drug or a compounded preparation containing the named ingredient. This is a labeling and evidence question, not individualized medication advice."]},
 {'h2':'Approval language is not an arrival guarantee','paragraphs':["Enhance.MD’s typical twenty-four-hour approval statement concerns a clinical decision stage. Wellorithm’s twenty-four-to-forty-eight-hour consultation language describes another early milestone. Both separately discuss delivery. Neither permits Clinic Scout to promise that an intake becomes a prescription, that a pharmacy has stock, or that a carrier will arrive on a fixed date.","A logistics record should list questionnaire completion, required consultation, prescription decision, pharmacy acceptance, fulfillment, carrier pickup, and delivery estimate. Keep those timestamps distinct. If a provider cannot identify the trigger for its advertised window, the safest interpretation is that the total elapsed time remains unknown."]},
 {'h2':'Cancellation evidence is still incomplete','paragraphs':["Wellorithm’s capture refers to canceling before the next shipment and includes refund language. Enhance.MD says cancellations and refunds are available subject to terms and conditions. Those are starting points, not full policies. The important details are the renewal cutoff, whether pharmacy processing makes a charge nonrefundable, treatment of shipped medication, and the channel required to cancel.","Save the policy displayed at checkout with the date and order reference. Do not rely on a comparison page to resolve a billing dispute. The role of this article is to expose the missing clauses before purchase and keep the two offers from being flattened into one monthly-price ranking."]},
 {'h2':'Which offer is more transparent depends on the question','paragraphs':["Wellorithm is more explicit about the difference between an introductory month and later recurring months. Enhance.MD presents lower captured headline figures and a simpler self-pay message. Wellorithm supplies more detail about payment flexibility and temperature-controlled fulfillment; Enhance.MD supplies a concise approval and support narrative. Neither wins every dimension.","Choose the comparison lens before the provider: recurring budget, commitment, route, human-review sequence, payment method, pharmacy evidence, or delivery. Then verify only the facts relevant to that lens. The score is an evidence-transparency tool, not a medical ranking and not a promise of results."]}
]
M.update({'article_id':'phase2-batch2-medium-verify-product-status-and-online-program-evidence-20260723','title':'How to verify an online GLP-1 program without confusing compounded and FDA-approved drugs','h1':'Verify the program, the product, and the paper trail separately','description':'A primary-source method for checking online GLP-1 claims, product status, provider identity, pricing, pharmacy language, and fulfillment without medical advice.','primary_keyword':'how to verify online GLP-1 program product status','canonical_path':'/guides/verify-online-glp-1-program-product-status/'})
M['sections']=[
 {'h2':'Verification has three separate objects','paragraphs':["A telehealth storefront, a licensed prescriber, and a dispensed drug are not the same object. A polished program page can describe access to care without proving the identity of every clinician. A clinician can be licensed without proving that a particular pharmacy or product has the status implied by marketing copy. A pharmacy can be licensed without turning a compounded drug into an FDA-approved product. Start by separating the program operator, the professional review, and the medication record.","This article is an editorial due-diligence method. It does not decide whether someone should use a medication, which product is appropriate, what dose to take, or how to respond to symptoms. Those questions belong with qualified healthcare professionals. The method focuses on claim provenance: who said it, where it appeared, what date it was captured, and what the source actually establishes."]},
 {'h2':'Let FDA control product-status language','paragraphs':["FDA says compounded drugs are not FDA-approved. The agency does not verify their safety, effectiveness, or quality before marketing. That sentence should anchor any page discussing compounded semaglutide or tirzepatide. A provider’s reference to an FDA-registered facility, a familiar ingredient, or a branded trademark does not override the regulator’s distinction.","When a page names Ozempic, Wegovy, Mounjaro, Zepbound, semaglutide, or tirzepatide, ask what will actually appear on the prescription and dispensing label. Record whether the product is an FDA-approved branded drug or a compounded preparation. Do not let a parenthetical trademark collapse those categories. If the answer remains unclear, mark product status unknown and stop short of a recommendation."]},
 {'h2':'Archive the exact commercial claim','paragraphs':["Capture the provider URL, page title, retrieval date, and exact sentence for price, commitment, review, shipping, insurance, HSA/FSA, cancellation, and pharmacy language. Keep the quote beside the normalized field. This prevents a summary such as “ships quickly” from outliving a source that actually said “five to seven business days after approval.” It also shows when a price was introductory rather than recurring.","Screenshots alone are hard to audit at scale, while normalized fields alone can conceal context. Keep both where possible, or preserve machine-readable extracts with source identifiers and exact quotations. Hash the research ledger before drafting so a later copy edit cannot silently change the evidence base."]},
 {'h2':'Verify organizational identity without overclaiming locality','paragraphs':["The NPPES NPI Registry can verify that an organization record exists, its enumeration type, status, location fields, and taxonomy data as of the query date. NPPES does not prove that the organization currently prescribes GLP-1 medication, accepts new patients, offers telehealth, takes insurance, has a certain price, or serves every address in a city. Those services require separate first-party evidence.","A directory page should therefore label an NPI record as identity evidence and reserve a direct-service flag for an organization-matched source that explicitly describes the service. If fewer than the release threshold have direct dated sources, keep the city page noindex and held. The honest limitation is more useful than a large inferred directory."]},
 {'h2':'Turn price into an all-in invoice question','paragraphs':["A starting price can omit the later-month amount, membership fee, consultation, laboratory work, supplies, shipping, refill review, or the difference between product forms. Build an invoice worksheet with first charge, recurring charge, plan duration, included items, conditional items, renewal date, cancellation cutoff, and refund terms. If a provider answers with another headline number, the evidence remains incomplete.","Coverage deserves the same precision. “Insurance accepted,” “insurance support,” “insurance not accepted,” and “HSA/FSA eligible” describe different payment paths. Do not infer one from another. CMS or plan documents may explain benefit rules, but a provider page cannot guarantee that a specific claim will be covered."]},
 {'h2':'Treat speed claims as a chain of milestones','paragraphs':["Separate intake, clinician review, prescription decision, pharmacy acceptance, fulfillment, carrier pickup, and doorstep delivery. A twenty-four-hour review statement does not mean medication arrives the next day. A five-to-seven-day shipping statement may begin only after processing. Ask which event starts the clock and whether weekends or destination rules are excluded.","For shipped medication, request the dispensing pharmacy identity, tracking process, storage instructions, and replacement policy. Do not infer quality from speed. The verification goal is to know which organization owns each step and which source supports the stated timing."]},
 {'h2':'Use red flags as stop rules, not dramatic copy','paragraphs':["Pause when a page describes a compounded product as FDA-approved, treats a trademark and compounded ingredient as interchangeable, promises guaranteed results, hides later recurring charges, omits the dispensing pharmacy from a shipped-product pathway, or substitutes a review badge for verifiable evidence. An exact FDA warning-letter match is a hard boundary for promotion until the compliance record changes and is independently re-reviewed.","A red flag does not authorize a medical or legal conclusion about an individual case. It changes the publication decision: hold the row, narrow the claim, archive the evidence, and ask for clarification. Fail closed rather than padding a top list."]},
 {'h2':'A publishable comparison needs a reproducible trail','paragraphs':["Before publication, a second reviewer should be able to start with the source ledger and reproduce every price, timeline, product-status label, and unknown field. The author line should identify the actual editorial organization or a real contributor; it should not invent a physician reviewer or credentials. Affiliate relationships and held links should be disclosed even when no outbound route is active.","The final checklist is compact: official source; exact quote; captured date; product category; clinician-review description; pharmacy evidence; first and recurring cost; logistics milestones; cancellation terms; state or service-area support; independent primary-source warning; and explicit unknowns. If that packet cannot be assembled, the page is not ready for indexing or promotion."]}
]
for art in [A,B,M]:
 art['word_count']=words(art['sections']); art['evidence_review']['content_sha256']=hashlib.sha256(json.dumps(art['sections'],sort_keys=True).encode()).hexdigest(); art['date_modified']='2026-07-23'
